// Get inputs
const query = $('MCP Trigger').item.json.query || '';
const mode = $('MCP Trigger').item.json.mode || 'all';
const queryLower = query.toLowerCase();

// Extract plain text from Google Docs API response
function extractText(content) {
  if (!content || !Array.isArray(content)) return '';
  let text = '';
  for (const element of content) {
    if (element.paragraph) {
      for (const el of element.paragraph.elements || []) {
        if (el.textRun && el.textRun.content) {
          text += el.textRun.content;
        }
      }
    } else if (element.table) {
      for (const row of element.table.tableRows || []) {
        for (const cell of row.tableCells || []) {
          text += extractText(cell.content) + ' | ';
        }
        text += '\n';
      }
    }
  }
  return text;
}

const docBody = $('Read Knowledge Base').item.json.body;
const fullText = extractText(docBody ? docBody.content : []);

if (!fullText || fullText.trim().length === 0) {
  return [{ json: { 
    result: 'Could not read the knowledge base. Please check the Google Doc ID and permissions.',
    query,
    sectionsFound: 0
  }}];
}

// Split document into sections by heading markers (# or ##)
const rawSections = fullText.split(/\n(?=#+ )/);

// Categorize sections
const storySection = [];
const cheatSection = [];
const techSection = [];
const otherSections = [];

for (const section of rawSections) {
  const s = section.trim();
  if (!s) continue;
  const lower = s.toLowerCase();
  if (lower.startsWith('# star') || lower.startsWith('## story') || lower.includes('star stories')) {
    storySection.push(s);
  } else if (lower.includes('cheat') || lower.includes('behavioral') || lower.includes('common question')) {
    cheatSection.push(s);
  } else if (lower.includes('tech stack') || lower.includes('technical') || lower.includes('skills')) {
    techSection.push(s);
  } else {
    otherSections.push(s);
  }
}

// Pick which sections to search based on mode
let searchPool;
switch (mode) {
  case 'stories': searchPool = storySection; break;
  case 'cheatsheet': searchPool = cheatSection; break;
  case 'techstack': searchPool = techSection; break;
  default: searchPool = rawSections;
}

if (searchPool.length === 0) searchPool = rawSections;

// Score each section by keyword relevance
const queryWords = queryLower
  .replace(/[^a-z0-9\s]/g, '')
  .split(' ')
  .filter(w => w.length > 3);

// Common interview keywords to boost
const interviewKeywords = [
  'leadership', 'conflict', 'failure', 'success', 'challenge', 
  'team', 'project', 'result', 'impact', 'decision', 'difficult',
  'proud', 'mistake', 'improve', 'learn', 'influence', 'prioritize',
  'deadline', 'stakeholder', 'mentor', 'feedback', 'ambiguous'
];

const scored = searchPool.map(section => {
  const sectionLower = section.toLowerCase();
  let score = 0;

  // Score query word matches
  for (const word of queryWords) {
    const count = (sectionLower.match(new RegExp(word, 'g')) || []).length;
    score += count * 2;
  }

  // Boost for interview keyword matches
  for (const keyword of interviewKeywords) {
    if (queryLower.includes(keyword) && sectionLower.includes(keyword)) {
      score += 3;
    }
  }

  // Boost Story sections slightly
  if (sectionLower.includes('## story') || sectionLower.includes('situation:')) {
    score += 1;
  }

  return { section: section.trim(), score };
});

// Get top 3 relevant sections
const topSections = scored
  .filter(s => s.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 3)
  .map(s => s.section);

let result;
if (topSections.length > 0) {
  result = `Found ${topSections.length} relevant section(s) for "${query}":\n\n` + 
           topSections.join('\n\n---\n\n');
} else {
  // Fallback: return full doc summary
  const preview = fullText.slice(0, 3000);
  result = `No exact match for "${query}". Here is the full knowledge base:\n\n${preview}${
    fullText.length > 3000 ? '\n\n[... document continues ...]' : ''
  }`;
}

return [{ json: { 
  result,
  query,
  sectionsFound: topSections.length,
  totalSections: rawSections.length
}}];
